import socket
import json

groups = {}

def process_message(message, addr):
    if "command" in message:
        if message["command"] == "private":
            recipient = tuple(message['recipient'])
            if recipient in clients:
                server_socket.sendto(json.dumps({"from": "Private from {}".format(addr), "content": message["content"]}).encode(), recipient)
            else:
                server_socket.sendto("Invalid recipient address.".encode(), addr)

        elif message["command"] == "create":
            group_name = message["group_name"]
            if group_name not in groups:
                groups[group_name] = {addr}
                server_socket.sendto("Group '{}' created successfully.".format(group_name).encode(), addr)
            else:
                server_socket.sendto("Group '{}' already exists.".format(group_name).encode(), addr)

        elif message["command"] == "join":
            group_name = message["group_name"]
            if group_name in groups:
                groups[group_name].add(addr)
                server_socket.sendto("Joined group '{}' successfully.".format(group_name).encode(), addr)
            else:
                server_socket.sendto("Group '{}' not found.".format(group_name).encode(), addr)

        elif message["command"] == "group_message":
            group_name = message["group_name"]
            if group_name in groups and addr in groups[group_name]:
                for group_member in groups[group_name]:
                    if group_member != addr:
                        server_socket.sendto(json.dumps({"from": "Group {}: {}".format(group_name, addr), "content": message["content"]}).encode(), group_member)
            else:
                server_socket.sendto("You are not a member of the group '{}'.".format(group_name).encode(), addr)

server_socket = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
server_socket.bind(('localhost', 12345))

clients = dict()

print("UDP Server started...")

try:
    while True:
        data, addr = server_socket.recvfrom(1024)
        clients[addr] = addr
        message = json.loads(data)

        print(f"{addr}: {message['content']}")

        if message['command'] == "message":
            for client_addr in clients:
                if client_addr != addr:
                    server_socket.sendto(json.dumps({"from": addr, "content": message['content']}).encode(), client_addr)
        else:
            process_message(message, addr)

except KeyboardInterrupt:
    print("\nUDP Server stopped.")
    server_socket.close()
```

